ALTER TABLE public.shipping_rules ADD COLUMN is_default boolean NOT NULL DEFAULT false;
CREATE UNIQUE INDEX shipping_rules_one_default ON public.shipping_rules(is_default) WHERE is_default;

CREATE OR REPLACE FUNCTION public.check_delivery(_pincode text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public
AS $function$ DECLARE s public.shipping_rules; BEGIN IF _pincode !~ '^[1-9][0-9]{5}$' THEN RAISE EXCEPTION 'Invalid PIN'; END IF; SELECT * INTO s FROM public.shipping_rules WHERE active AND (pincode=_pincode OR is_default) ORDER BY (pincode=_pincode) DESC LIMIT 1; IF NOT FOUND THEN RETURN jsonb_build_object('serviceable',false,'cod_enabled',false); END IF; RETURN jsonb_build_object('serviceable',s.cod_enabled,'fee_paise',s.fee_paise,'min_days',s.min_days,'max_days',s.max_days,'cod_enabled',s.cod_enabled); END $function$;

CREATE OR REPLACE FUNCTION public.quote_cod_order(_items jsonb,_pincode text,_coupon text DEFAULT '') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE i jsonb; p public.products; s public.shipping_rules; c public.coupons; qty integer; sub bigint:=0; disc bigint:=0; tax bigint:=0; reason text:=NULL; result jsonb; BEGIN
IF jsonb_typeof(_items) IS DISTINCT FROM 'array' OR jsonb_array_length(_items) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Invalid cart'; END IF;
IF (SELECT count(DISTINCT value->>'productId') FROM jsonb_array_elements(_items))<>jsonb_array_length(_items) THEN RAISE EXCEPTION 'Duplicate cart item'; END IF;
SELECT * INTO s FROM public.shipping_rules WHERE active AND (pincode=_pincode OR is_default) ORDER BY (pincode=_pincode) DESC LIMIT 1;
IF NOT FOUND THEN reason:='Delivery is not configured for this PIN'; END IF;
FOR i IN SELECT value FROM jsonb_array_elements(_items) LOOP
qty:=(i->>'quantity')::integer; IF qty IS NULL OR qty NOT BETWEEN 1 AND 20 THEN RAISE EXCEPTION 'Invalid quantity'; END IF;
SELECT * INTO p FROM public.products WHERE id=i->>'productId' AND status='active'; IF NOT FOUND THEN RAISE EXCEPTION 'Product unavailable'; END IF;
sub:=sub+p.price_paise::bigint*qty;
IF p.is_demo THEN reason:='Demonstration products cannot be ordered'; ELSIF p.tax_bps IS NULL THEN reason:='Product tax settings require verification'; END IF;
IF p.fulfillment_model='OWN_INVENTORY' AND NOT EXISTS(SELECT 1 FROM public.inventory WHERE product_id=p.id AND quantity-reserved>=qty) THEN reason:=coalesce(reason,'Insufficient stock'); END IF;
IF p.fulfillment_model='DROPSHIP' AND NOT EXISTS(SELECT 1 FROM public.supplier_products sp JOIN public.suppliers ss ON ss.id=sp.supplier_id WHERE sp.product_id=p.id AND sp.available AND ss.approved AND ss.manual_fulfillment) THEN reason:=coalesce(reason,'Supplier availability is not confirmed'); END IF;
END LOOP;
IF length(trim(_coupon))>0 THEN SELECT * INTO c FROM public.coupons WHERE code=upper(trim(_coupon)) AND active AND starts_at<=now() AND ends_at>now() AND sub>=min_subtotal_paise; IF NOT FOUND THEN RAISE EXCEPTION 'Coupon invalid or expired'; END IF; disc:=least(c.max_discount_paise,round(sub*c.percent/100.0)::bigint); END IF;
FOR i IN SELECT value FROM jsonb_array_elements(_items) LOOP SELECT * INTO p FROM public.products WHERE id=i->>'productId'; IF NOT p.tax_inclusive THEN tax:=tax+round(p.price_paise::numeric*(i->>'quantity')::integer*(1-CASE WHEN sub>0 THEN disc::numeric/sub ELSE 0 END)*coalesce(p.tax_bps,0)/10000)::bigint; END IF; END LOOP;
IF sub+tax+coalesce(s.fee_paise,0)-disc>2147483647 THEN RAISE EXCEPTION 'Order value too large'; END IF;
RETURN jsonb_build_object('subtotal',sub,'discount',disc,'tax',tax,'shipping',s.fee_paise,'payable',CASE WHEN reason IS NULL THEN sub-disc+tax+s.fee_paise ELSE NULL END,'purchasingEnabled',reason IS NULL,'paymentMethod','COD','reason',reason,'minDays',s.min_days,'maxDays',s.max_days);
END $$;

CREATE OR REPLACE FUNCTION public.reserve_customer_order(_user uuid,_address uuid,_items jsonb,_key uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o uuid; a public.addresses; s public.shipping_rules; p public.products; i jsonb; qty integer; sub integer:=0; tax integer:=0; item_id uuid; supplier uuid; BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(_user::text,0)); SELECT id INTO o FROM public.orders WHERE user_id=_user AND idempotency_key=_key; IF FOUND THEN RETURN o; END IF; IF jsonb_typeof(_items)<>'array' OR jsonb_array_length(_items) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Invalid cart'; END IF; IF (SELECT count(DISTINCT value->>'productId') FROM jsonb_array_elements(_items))<>jsonb_array_length(_items) THEN RAISE EXCEPTION 'Duplicate cart item'; END IF; SELECT * INTO a FROM public.addresses WHERE id=_address AND user_id=_user; IF NOT FOUND THEN RAISE EXCEPTION 'Address unavailable'; END IF; SELECT * INTO s FROM public.shipping_rules WHERE active AND (pincode=a.pincode OR is_default) ORDER BY (pincode=a.pincode) DESC LIMIT 1; IF NOT FOUND THEN RAISE EXCEPTION 'Delivery not configured'; END IF; INSERT INTO public.orders(user_id,total_paise,address_snapshot,idempotency_key,reservation_expires_at,shipping_paise) VALUES(_user,0,to_jsonb(a)-'user_id',_key,now()+interval '15 minutes',s.fee_paise) RETURNING id INTO o; FOR i IN SELECT value FROM jsonb_array_elements(_items) ORDER BY value->>'productId' LOOP qty:=(i->>'quantity')::integer; IF qty NOT BETWEEN 1 AND 20 THEN RAISE EXCEPTION 'Invalid quantity'; END IF; SELECT * INTO p FROM public.products WHERE id=i->>'productId' AND status='active' FOR UPDATE; IF NOT FOUND OR p.is_demo OR p.tax_bps IS NULL OR p.tax_bps NOT BETWEEN 0 AND 10000 THEN RAISE EXCEPTION 'Product not approved for sale'; END IF; supplier:=NULL; IF p.fulfillment_model='OWN_INVENTORY' THEN UPDATE public.inventory SET reserved=reserved+qty WHERE product_id=p.id AND quantity-reserved>=qty; IF NOT FOUND THEN RAISE EXCEPTION 'Insufficient stock'; END IF; ELSE SELECT sp.supplier_id INTO supplier FROM public.supplier_products sp JOIN public.suppliers ss ON ss.id=sp.supplier_id WHERE sp.product_id=p.id AND sp.available AND ss.approved AND ss.manual_fulfillment ORDER BY sp.id LIMIT 1; IF NOT FOUND THEN RAISE EXCEPTION 'Supplier unavailable'; END IF; END IF; sub:=sub+p.price_paise*qty; tax:=tax+CASE WHEN p.tax_inclusive THEN 0 ELSE round(p.price_paise*qty*p.tax_bps/10000.0)::integer END; INSERT INTO public.order_items(order_id,product_id,name,sku,quantity,unit_price_paise,tax_bps,return_days,fulfillment_model) VALUES(o,p.id,p.name,p.sku,qty,p.price_paise,p.tax_bps,p.return_days,p.fulfillment_model) RETURNING id INTO item_id; INSERT INTO public.fulfillments(order_id,item_id,supplier_id) VALUES(o,item_id,supplier); END LOOP; UPDATE public.orders SET subtotal_paise=sub,tax_paise=tax,total_paise=sub+tax+s.fee_paise WHERE id=o; RETURN o; END $$;